package dev.zomboid.gore;
import java.util.*;
/** Disconnected remnants are not kept suspended in the source body mesh. */
public final class Connected48 {
 static boolean touch(Mesh12.Box a,Mesh12.Box b){float e=.045f;return a.x0()<=b.x1()+e&&a.x1()+e>=b.x0()&&a.y0()<=b.y1()+e&&a.y1()+e>=b.y0()&&a.z0()<=b.z1()+e&&a.z1()+e>=b.z0();}
 static double volume(Mesh12.Box b){return Math.max(0,b.x1()-b.x0())*Math.max(0,b.y1()-b.y0())*Math.max(0,b.z1()-b.z0());}
 static List<Mesh12.Box> connected(List<Mesh12.Box> boxes){if(boxes.size()<2)return boxes;boolean[]seen=new boolean[boxes.size()];List<Mesh12.Box> best=List.of();double weight=-1;for(int i=0;i<boxes.size();i++){if(seen[i])continue;List<Mesh12.Box> group=new ArrayList<>();ArrayDeque<Integer> queue=new ArrayDeque<>();queue.add(i);seen[i]=true;double v=0;while(!queue.isEmpty()){int j=queue.removeFirst();Mesh12.Box b=boxes.get(j);group.add(b);v+=volume(b);for(int k=0;k<boxes.size();k++)if(!seen[k]&&touch(b,boxes.get(k))){seen[k]=true;queue.add(k);}}if(v>weight){weight=v;best=group;}}return best;}
 static boolean contains(Mesh12.Box b,float x,float y,float z){float e=.06f;return x>=b.x0()-e&&x<=b.x1()+e&&y>=b.y0()-e&&y<=b.y1()+e&&z>=b.z0()-e&&z<=b.z1()+e;}
 public static List<Mesh12.Quad> filter(List<Mesh12.Quad> mesh,List<Mesh12.Cube> cubes,int region){if(mesh.isEmpty()||cubes.isEmpty()||!Cuts24.has(region))return mesh;Mesh12.Box bound=CSG24.bounds(cubes);List<Mesh12.Box> all=new ArrayList<>(CSG24.remainder(bound,CSG24.holes(bound,region,0)));if(Model14.internal())for(Anatomy14.Piece p:Anatomy14.anatomy(region)){if(Organ29.removed(p.name(),region,p.box()))continue;double depth=p.material()==2||p.name().equals("tooth")?.85:Anatomy27.organ(p.name())?1.05:.4;all.addAll(CSG24.remainder(Anatomy14.scale(p.box(),bound),CSG24.holes(bound,region,depth)));}if(all.isEmpty())return List.of();List<Mesh12.Box> keep=connected(all);if(keep.size()==all.size())return mesh;List<Mesh12.Quad> out=new ArrayList<>();for(Mesh12.Quad q:mesh){float x=0,y=0,z=0;for(Mesh12.Vertex v:q.vertices()){x+=v.x()/4;y+=v.y()/4;z+=v.z()/4;}for(Mesh12.Box b:keep)if(contains(b,x,y,z)){out.add(q);break;}}return List.copyOf(out);}
}
